(Cutoffs and the spectrum of $\boldsymbol{\underline{\underline{\varepsilon}}}$)
From \eqref{dieltens_Stixframe}, it is clear that the eigenvalues of $\boldsymbol{\underline{\underline{\varepsilon}}}$ at every $\boldsymbol{x} \in \Omega$ are
\begin{equation}
\lambda_1(\boldsymbol{x}) = S(\boldsymbol{x}) + D(\boldsymbol{x}), \quad \lambda_2(\boldsymbol{x}) = S(\boldsymbol{x}) - D(\boldsymbol{x}) \quad \text{and} \quad \lambda_3(\boldsymbol{x}) = P(\boldsymbol{x}).
 \label{eigenvals_dieltens}
\end{equation}
Therefore, for both polarizations, at least one eigenvalue is zero at the cutoff position.
\label{remark_cutoff_spectrum_dieltens}

Let ${\boldsymbol{\mathsf{W}}}_k$ be an eigenvector with eigenvalue $\lambda_k$, then
\begin{align*}
 &\lambda_k {\boldsymbol{\mathsf{W}}}_k^T \mathbb{M} {\boldsymbol{\mathsf{W}}}_k = \left[ \left( \mathbb{I} - (\Delta t/2) (\mathbb{P} + \mathbb{N}) \mathbb{M} \right) {\boldsymbol{\mathsf{W}}}_k \right]^T \mathbb{M} {\boldsymbol{\mathsf{W}}}_k =  {\boldsymbol{\mathsf{W}}}_k^T \mathbb{M} {\boldsymbol{\mathsf{W}}}_k - (\Delta t/2) \left[  (\mathbb{P} + \mathbb{N}) \mathbb{M}  {\boldsymbol{\mathsf{W}}}_k \right]^T \mathbb{M} {\boldsymbol{\mathsf{W}}}_k\\
 &\Rightarrow  (1 - \lambda_k) {\boldsymbol{\mathsf{W}}}_k^T \mathbb{M} {\boldsymbol{\mathsf{W}}}_k = (\Delta t/2) \left(  \mathbb{N} \mathbb{M}  {\boldsymbol{\mathsf{W}}}_k \right)^T \mathbb{M} {\boldsymbol{\mathsf{W}}}_k \le 0 \quad \Rightarrow \lambda_k \ge 1.
\end{align*}
In particular, $\lambda_k \neq 0 $, thus $\mathbb{I} - (\Delta t/2) (\mathbb{P} + \mathbb{N}) \mathbb{M} $ is invertible.

Assume ${\boldsymbol{\mathsf{f}}}={\boldsymbol{\mathsf{0}}}$, then ${\boldsymbol{\mathsf{U}}}^{n+1} = \mathbb{K} {\boldsymbol{\mathsf{U}}}^n$ and it holds that
 \begin{align*}
 \|\mathbb{K}{\boldsymbol{\mathsf{U}}}^n\|^2_\mathbb{M} - \|{\boldsymbol{\mathsf{U}}}^n\|^2_\mathbb{M} &= ({\boldsymbol{\mathsf{U}}}^{n+1} - {\boldsymbol{\mathsf{U}}}^n)^T \mathbb{M} ({\boldsymbol{\mathsf{U}}}^{n+1} - {\boldsymbol{\mathsf{U}}}^n) = \cfrac{\Delta t}{2} \left [ (\mathbb{P} + \mathbb{N}) \mathbb{M} ({\boldsymbol{\mathsf{U}}}^{n+1} + {\boldsymbol{\mathsf{U}}}^n) \right]^T  \mathbb{M} ({\boldsymbol{\mathsf{U}}}^{n+1} - {\boldsymbol{\mathsf{U}}}^n)  \\
 &= \cfrac{\Delta t}{2} \left [ \mathbb{N} \mathbb{M} ({\boldsymbol{\mathsf{U}}}^{n+1} + {\boldsymbol{\mathsf{U}}}^n) \right]^T \mathbb{M} ({\boldsymbol{\mathsf{U}}}^{n+1} - {\boldsymbol{\mathsf{U}}}^n)  \le 0,
\end{align*}
since $\mathbb{P}$ is skew-symmetric and $\mathbb{N}$ is negative semi-definite.
